","newContent":"const express = require("express");
const axios = require("axios");
const cheerio = require("cheerio");

const app = express();
const PORT = process.env.PORT || 3000;
const BASE = "https://desidubanime.me";

// ── HTTP client ──
const http = axios.create({
  baseURL: BASE,
  timeout: 25000,
  headers: {
    "User-Agent":
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
      "(KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
    Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.5",
  },
});

// ── Helpers ──

function load$(html) { return cheerio.load(html); }

/** Collapse whitespace */
function cleanText(raw) {
  if (!raw) return null;
  return raw.replace(/[\t\n\r]+/g, " ").replace(/\s{2,}/g, " ").trim();
}

/** Extract slug from URL */
function slug(href) {
  if (!href) return null;
  const m = href.match(/\/([^/]+)\/?$/);
  return m ? m[1] : href.replace(/\/$/, "").split("/").pop();
}

/** Element-level text */
function ct($, el, sel) {
  const f = $(el).find(sel).first();
  return f.length ? cleanText(f.text()) : null;
}

/** Element-level attr */
function ca($, el, sel, attr) {
  const f = $(el).find(sel).first();
  return f.length ? f.attr(attr) : null;
}

/** Doc-level text */
function dct($, sel) {
  const f = $(sel).first();
  return f.length ? cleanText(f.text()) : null;
}

/** Doc-level attr */
function dca($, sel, attr) {
  const f = $(sel).first();
  return f.length ? f.attr(attr) : null;
}

/** Normalize title: remove "#N Spotlight", leading numbers */
function cleanTitle(raw) {
  if (!raw) return null;
  let t = cleanText(raw);
  t = t.replace(/^#\d+\s*Spotlight\s*/i, "");
  t = t.replace(/^\d+(\.\d+)?\s+/, "");
  return t || null;
}

/** Deduplicate title: "Naruto Naruto" -> "Naruto", "Name Name Season 2 Name Name Season 2" -> "Name Name Season 2" */
function dedupTitle(t) {
  if (!t) return t;
  // Try splitting by multiple spaces first
  let parts = t.split(/\s{2,}/);
  if (parts.length === 1) parts = t.split(/\s+/);
  if (parts.length >= 2 && parts.length % 2 === 0) {
    const mid = parts.length / 2;
    const firstHalf = parts.slice(0, mid).join(" ");
    const secondHalf = parts.slice(mid).join(" ");
    if (firstHalf === secondHalf) return firstHalf;
  }
  // Simple case: first and last word match
  if (parts.length >= 2 && parts[0].trim() === parts[parts.length - 1].trim()) {
    return parts.slice(0, -1).join(" ");
  }
  return t;
}

/** Noise keywords to filter from episode lists */
const EP_NOISE = /^(watch now|detail|info|comments|read more|view more|load more|share|copy|telegram|reddit|facebook|whatsapp|tumblr|x|report problem|auto next|fast.rewind|fast.forward|playlist.add|closed.caption|mic|dub|sub|mirror|playerx|abyss|fullscreen|report|load more episodes|load more comments|reply|delete|cancel|submit comment|update watchlist|please log in|sign in|register|reset password|search|menu|filter|view all|login|sign up|log in|episode lists|order by|latest episode|first episode|search episodes|characters|trailer|comments & review|overview|information|season & episode|popular post|watch history|join now|contact us|disclaimer|dmca|copyright|az list|genres|languages|genre|next|prev|navigate_next|keyboard_arrow_down|sentiment|star|voted|vote now|share this anime|share anime)$/i;

function isNoise(text) {
  if (!text) return true;
  if (text.length < 2) return true;
  if (text.length > 100) return false;
  if (EP_NOISE.test(text)) return true;
  return false;
}

// ── ROUTES ──

// GET /api/home
app.get("/api/home", async (_req, res) => {
  try {
    const { data } = await http.get("/");
    const $ = load$(data);

    // Spotlight
    const spotlight = [];
    const seenSpot = new Set();
    $(".swiper-slide, [class*='spotlight'], .spotlight-item").each((_, el) => {
      const a = $(el).find("a[href*='/anime/']").first();
      const href = a.attr("href") || $(el).find("a[href]").first().attr("href");
      const s = slug(href);
      if (!s || seenSpot.has(s)) return;
      seenSpot.add(s);
      const img = $(el).find("img").first().attr("src") ||
        $(el).find("img").first().attr("data-src") ||
        $(el).find("img").first().attr("data-lazy-src");
      const h3 = cleanText($(el).find("h3").first().text());
      const aTitle = cleanText(a.attr("title") || a.text());
      const title = cleanTitle(h3 || aTitle);
      if (title && title.length > 1) spotlight.push({ title, slug: s, img });
    });

    // Latest episodes from watch links
    const latest = [];
    const seenLatest = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      const s = slug(href);
      if (!s || seenLatest.has(s) || !href.match(/\/watch\//)) return;
      seenLatest.add(s);
      const card = $(a).closest(".card, .item, article, .anime-card, .episode-card, .movie-card, [class*='card']") || $(a).parent().parent();
      const title = cleanTitle(ct($, card, ".title, h3, h4") || cleanText($(a).text()));
      const img = ca($, card, "img", "src") || ca($, card, "img", "data-src") || ca($, card, "img", "data-lazy-src");
      const eps = ct($, card, ".ep, .episode, .episodes");
      const rating = ct($, card, ".rating, .score, .star");
      const views = ct($, card, ".views, .view-count");
      const lang = ct($, card, ".language, .dub, .sub, .lang");
      if (title && title.length > 1 && !isNoise(title)) latest.push({ title, slug: s, img, eps, rating, views, lang });
    });

    // Categorised sections
    const sections = {};
    $("section, .section, .home-section").each((_, sec) => {
      const heading = cleanText($(sec).find("h2, h3, .heading, .section-title").first().text());
      if (!heading || heading.length < 2 || heading.length > 50) return;
      if (!sections[heading]) sections[heading] = [];
      $(sec).find("a[href*='/anime/']").each((_, a) => {
        const href = $(a).attr("href");
        const s = slug(href);
        if (!s || sections[heading].find(x => x.slug === s)) return;
        const card = $(a).closest(".card, .item, article, div");
        const title = cleanTitle(ct($, card, ".title, h3, h4") || cleanText($(a).text()));
        const img = ca($, card, "img", "src") || ca($, card, "img", "data-src");
        const eps = ct($, card, ".ep, .episode");
        const rating = ct($, card, ".rating, .score");
        const views = ct($, card, ".views, .view-count");
        if (title && title.length > 1 && !isNoise(title))
          sections[heading].push({ title, slug: s, img, eps, rating, views });
      });
    });

    // Classify sections
    const popular = [], movies = [], completed = [], upcoming = [], topAiring = [];
    Object.entries(sections).forEach(([heading, items]) => {
      const h = heading.toLowerCase();
      if (h.includes("popular")) popular.push(...items);
      else if (h.includes("top airing")) topAiring.push(...items);
      else if (h.includes("movie")) movies.push(...items);
      else if (h.includes("completed")) completed.push(...items);
      else if (h.includes("upcoming")) upcoming.push(...items);
      else if (h.includes("latest episode")) {} // already captured
      else popular.push(...items); // fallback
    });

    res.json({
      success: true,
      data: {
        spotlight: spotlight.slice(0, 10),
        latest: latest.slice(0, 30),
        popular: popular.slice(0, 15),
        topAiring: topAiring.slice(0, 15),
        movies: movies.slice(0, 15),
        completed: completed.slice(0, 15),
        upcoming: upcoming.slice(0, 15),
      },
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/anime?page=1
app.get("/api/anime", async (req, res) => {
  try {
    const page = Number(req.query.page) || 1;
    const url = page > 1 ? `/anime/page/${page}/` : "/anime/";
    const { data } = await http.get(url);
    const $ = load$(data);

    const animes = [];
    const seen = new Set();
    $(".card, .item, article, .anime-card, [class*='anime-card']").each((_, el) => {
      const link = $(el).find("a[href*='/anime/']").first();
      const href = link.attr("href") || $(el).find("a[href]").first().attr("href");
      const s = slug(href);
      if (!s || seen.has(s)) return;
      seen.add(s);
      const title = cleanTitle(ct($, el, ".title, h3, h4, a[title]") || cleanText(link.text()));
      if (!title || isNoise(title)) return;
      const img = ca($, el, "img", "src") || ca($, el, "img", "data-src") || ca($, el, "img", "data-lazy-src");
      animes.push({
        title,
        slug: s,
        img,
        type: ct($, el, ".type, .format"),
        eps: ct($, el, ".ep, .episode, .episodes"),
        rating: ct($, el, ".rating, .score, .star"),
        lang: ct($, el, ".language, .dub, .sub"),
        status: ct($, el, ".status, .airing-status"),
        year: ct($, el, ".year, .season-year"),
        synopsis: ct($, el, ".synopsis, .summary, .description, p"),
      });
    });

    const lastPage = $(".pagination a:last-child, .pagination .last, nav a:last, .page-numbers:last");
    let totalPages = page;
    if (lastPage.length) {
      const t = parseInt(lastPage.text().trim());
      if (!isNaN(t) && t > 0) totalPages = t;
    }

    res.json({ success: true, data: { animes: animes.slice(0, 30), currentPage: page, totalPages } });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/anime/:slug
app.get("/api/anime/:slug", async (req, res) => {
  try {
    const { data } = await http.get(`/anime/${req.params.slug}/`);
    const $ = load$(data);

    const title = dedupTitle(dct($, "h1, .anime-title, .title") || req.params.slug.replace(/-/g, " "));
    const overview = dct($, ".overview, .description, .synopsis, .summary, [itemprop='description'], .anime-description");
    const img = dca($, "img.poster, img.cover, img.anime-cover, .poster img, .anime-poster img", "src") ||
      dca($, "img.poster, img.cover, img.anime-cover, .poster img, .anime-poster img", "data-src");
    const rating = dct($, ".rating, .score, .star, .vote");
    const views = dct($, ".views, .view-count, .total-views");

    // Extract metadata from page text.
    // The site renders metadata as: "Native X Synonyms Y English Z Type TV Episodes 220 ..."
    // But the full body includes JS, menus etc. that also contain these words.
    // Narrow to the metadata region: from "Native" to before "var commentConfig" or "Comments"
    let fullText = cleanText($("body").text());
    // Try to isolate just the metadata block
    const metaStart = fullText.search(/Native\s+\S/i);
    const metaEnd = fullText.search(/var commentConfig|Comments\s+You can use|Order by:|Naruto:/i);
    if (metaStart >= 0) {
      const end = metaEnd > metaStart ? metaEnd : fullText.length;
      fullText = fullText.slice(metaStart, end);
    }
    const FIELD_ORDER = [
      "Native", "Synonyms", "English", "Type", "Episodes", "Aired",
      "Season", "Released Year", "Premiered", "Studios", "Genres",
      "Producers", "Licensors", "Tags", "Status", "Duration",
    ];

    // Build a map of { fieldName: "value between this field and the next" }
    const fieldValues = {};
    for (let i = 0; i < FIELD_ORDER.length; i++) {
      const label = FIELD_ORDER[i];
      const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      // Find this label in the text
      const startRe = new RegExp(escaped + "\\s+", "i");
      const startMatch = fullText.match(startRe);
      if (!startMatch) continue;
      const startIdx = startMatch.index + startMatch[0].length;

      // Find the NEXT field label that appears after this one
      let endIdx = fullText.length;
      for (let j = i + 1; j < FIELD_ORDER.length; j++) {
        const nextLabel = FIELD_ORDER[j];
        const nextEscaped = nextLabel.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const nextRe = new RegExp("\\s+" + nextEscaped + "\\s+", "i");
        const remaining = fullText.slice(startIdx);
        const nextMatch = remaining.match(nextRe);
        if (nextMatch && nextMatch.index < endIdx - startIdx) {
          endIdx = startIdx + nextMatch.index;
          break; // stop at first matching next field
        }
      }
      let val = fullText.slice(startIdx, endIdx).trim();
      if (val) fieldValues[label] = val;
    }

    // Also check for "Released Year" or "Premiered" (some pages use one, some the other)
    const year = fieldValues["Released Year"] || fieldValues["Premiered"];

    // If the structured approach failed, fall back to simple regex extraction
    const xfSimple = (label) => {
      const re = new RegExp(
        label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*(.+?)(?:\\s{2,}|$)", "i"
      );
      const m = fullText.match(re);
      return m ? m[1].trim().substring(0, 150) : null; // limit length to avoid grabbing everything
    };

    const native = fieldValues["Native"] || xfSimple("Native");
    const synonyms = fieldValues["Synonyms"] || xfSimple("Synonyms");
    const english = fieldValues["English"] || xfSimple("English");
    const type = fieldValues["Type"] || xfSimple("Type");
    const episodes = fieldValues["Episodes"] || xfSimple("Episodes");
    const aired = fieldValues["Aired"] || xfSimple("Aired");
    const season = fieldValues["Season"] || xfSimple("Season");
    const studios = fieldValues["Studios"] || xfSimple("Studios");
    const genres = fieldValues["Genres"] || xfSimple("Genres");
    const producers = fieldValues["Producers"] || xfSimple("Producers");
    const licensors = fieldValues["Licensors"] || xfSimple("Licensors");
    const tags = (fieldValues["Tags"] || xfSimple("Tags") || "").split(" Order by:")[0].trim().substring(0, 200) || null;
    const status = fieldValues["Status"] || xfSimple("Status");
    const duration = fieldValues["Duration"] || xfSimple("Duration");

    // Episodes: try from watch links on the page
    const eps = [];
    const seenEp = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      if (!href || seenEp.has(href)) return;
      const epTitle = cleanText($(a).text());
      if (!epTitle || isNoise(epTitle)) return;
      seenEp.add(href);
      const epNum = epTitle.match(/^(\d+)/);
      eps.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
    });

    // If few/no episodes found (JS-rendered list), fetch from watch page sidebar
    let episodesFromWatch = [];
    if (eps.length < 2) {
      const watchLink = $("a[href*='/watch/']").first().attr("href");
      if (watchLink) {
        try {
          const watchSlug = slug(watchLink);
          const { data: wData } = await http.get(`/watch/${watchSlug}/`);
          const w$ = load$(wData);
          w$("a[href*='/watch/']").each((_, a) => {
            const href = w$(a).attr("href");
            if (!href || seenEp.has(href)) return;
            const epTitle = cleanText(w$(a).text());
            if (!epTitle || isNoise(epTitle)) return;
            seenEp.add(href);
            const epNum = epTitle.match(/^(\d+)/);
            episodesFromWatch.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
          });
        } catch (_) {}
      }
    }

    // Related
    const related = [];
    const seenRel = new Set();
    $("a[href*='/anime/']").each((_, a) => {
      const href = $(a).attr("href");
      const relTitle = cleanText($(a).text());
      if (href && relTitle && relTitle.length > 3 && relTitle.length < 80 && !isNoise(relTitle) && !seenRel.has(href)) {
        seenRel.add(href);
        related.push({ title: relTitle, slug: slug(href) });
      }
    });

    res.json({
      success: true,
      data: {
        title, native, synonyms, english, type, episodes, aired, season,
        year, studios, genres, producers, licensors, tags, status, duration,
        rating, views, img, overview,
        episodesList: eps.length ? eps : episodesFromWatch,
        related: related.slice(0, 10),
      },
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/watch/:slug
app.get("/api/watch/:slug", async (req, res) => {
  try {
    const { data } = await http.get(`/watch/${req.params.slug}/`);
    const $ = load$(data);

    // Servers
    const servers = [];

    // 1) data-embed-id spans: format is base64(name):base64(url)
    $("[data-embed-id]").each((_, el) => {
      const raw = $(el).attr("data-embed-id");
      if (!raw || !raw.includes(":")) return;
      const [b64Name, b64Url] = raw.split(":");
      let name, url;
      try { name = Buffer.from(b64Name, "base64").toString("utf-8"); } catch (_) { name = null; }
      try { url = Buffer.from(b64Url, "base64").toString("utf-8"); } catch (_) { url = null; }
      // Some servers encode an HTML iframe snippet instead of a plain URL — extract the src
      if (url && (url.includes("<") || url.includes("iframe"))) {
        const iframeMatch = url.match(/src=['"]([^'"]+)['"]/i);
        if (iframeMatch) url = iframeMatch[1];
      }
      // Also grab the visible label text as fallback
      const label = cleanText($(el).text());
      if (!name && label) name = label;
      if (!name) name = "server";
      if (!url) return;
      const active = $(el).hasClass("active") || $(el).attr("class")?.includes("active");
      if (!servers.find(s => s.url === url)) servers.push({ name, url, active: !!active });
    });

    // 2) Iframes (backup — usually already covered by data-embed-id)
    $("iframe").each((_, el) => {
      const src = $(el).attr("src");
      if (src && !servers.find(s => s.url === src)) {
        const label = src.includes("gdmirrorbot") ? "Mirror" : src.includes("abyss") ? "Abyss" : src.includes("vidmoly") ? "VMoly" : src.includes("playerp2p") ? "Streamp2p" : "embed";
        servers.push({ name: label, url: src });
      }
    });

    // 3) Legacy fallback — buttons/divs with data-server/data-url attrs
    $("button, a, div").each((_, el) => {
      const text = cleanText($(el).text());
      const dataServer = $(el).attr("data-server") || $(el).attr("data-name");
      const dataUrl = $(el).attr("data-url") || $(el).attr("data-src");
      const href = $(el).attr("href");
      if ((text && /^(Mirror|PlayerX|Abyss|Server|Stream|HD|SD|\d+)$/i.test(text)) || dataServer) {
        const name = dataServer || text || "server";
        const url = dataUrl || href || null;
        if (url && !servers.find(s => s.url === url)) servers.push({ name, url });
      }
    });

    // Current episode
    const currentEpisode = dct($, "h1, .title, .episode-title") || "";

    // Episode list
    const eps = [];
    const seenEp = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      if (!href || seenEp.has(href)) return;
      seenEp.add(href);
      const epTitle = cleanText($(a).text());
      if (!epTitle || isNoise(epTitle)) return;
      const epNum = epTitle.match(/^(\d+)/);
      eps.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
    });

    // Anime info
    const title = dct($, ".anime-title, .show-title, .series-name, h2, .series-title");
    const img = dca($, "img.poster, img.cover, img.anime-cover, .poster img", "src") ||
      dca($, "img.poster, img.cover, img.anime-cover, .poster img", "data-src");
    const rating = dct($, ".rating, .score, .star");
    const type = dct($, ".type, .format");
    const lang = dct($, ".language, .dub-tag, .sub-tag");
    const synopsis = dct($, ".overview, .description, .synopsis, .summary");

    // Prev / Next
    const prevHref = $("a.prev, .prev-episode a, a[rel='prev']").first().attr("href");
    const nextHref = $("a.next, .next-episode a, a[rel='next']").first().attr("href");

    res.json({
      success: true,
      data: {
        title: cleanText(title),
        img, rating, type, lang, synopsis,
        currentEpisode: cleanText(currentEpisode),
