      if (!name || name.length <= 1) return;
      const cm = name.match(/\((\d+)\)\s*$/);
      const count = cm ? cm[1] : null;
      name = name.replace(/\s*\(\d+\)\s*$/, "").trim();
      if (name && !genres.find(g => g.name === name)) genres.push({ name, count, slug: slug($(el).attr("href") || "") });
    });

    if (!genres.length) {
      $(".genre-nav a, .genre-menu a, .sidebar a[href*='genre'], .filter a[href*='genre']").each((_, a) => {
        let name = cleanText($(a).text());
