        const count = cm ? cm[1] : null;
        if (name) name = name.replace(/\s*\(\d+\)\s*$/, "").trim();
        if (name && name.length > 1 && !genres.find(g => g.name === name)) genres.push({ name, count, slug: slug($(a).attr("href") || "") });
      });
    }

    res.json({ success: true, data: { genres } });
  } catch (err) {
