                </button>
                <a href="#" className="liquid-glass rounded-full px-6 py-3 text-sm font-medium text-white/90 font-body">
                  Learn More
                </a>
              </div>
            </Anim>
          </div>

          {/* Footer grid */}
          <div className="px-8 md:px-16 lg:px-20 py-12 border-t border-white/5">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-10">
              {/* Logo + tagline */}
              <div className="col-span-2 md:col-span-1">
                <div className="liquid-glass rounded-full w-10 h-10 flex items-center justify-center mb-4">
                  <span className="font-heading italic text-white text-lg lowercase">a</span>
                </div>
                <p className="text-sm text-white/50 font-body font-light leading-relaxed max-w-[24ch]">
                  Pioneering the next chapter of human exploration beyond Earth.
                </p>
              </div>

              {/* Link columns */}
              {footerLinks.map(function (col) {
                return (
                  <div key={col.heading}>
                    <h4 className="text-xs font-body font-semibold text-white/40 uppercase tracking-widest mb-4">
                      {col.heading}
                    </h4>
                    <ul className="space-y-2.5">
                      {col.links.map(function (link) {
                        return (
                          <li key={link}>
                            <a href="#" className="text-sm text-white/70 font-body font-light hover:text-white transition-colors">
                              {link}
                            </a>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Bottom bar */}
          <div className="px-8 md:px-16 lg:px-20 py-6 border-t border-white/5 flex flex-col md:flex-row items-center justify-between gap-4">
            <p className="text-xs text-white/30 font-body font-light">
              &copy; 2026 Aether Space. All rights reserved.
            </p>
            <div className="flex items-center gap-6">
              {["Privacy Policy", "Terms of Service", "Cookie Preferences"].map(function (link) {
                return (
                  <a key={link} href="#" className="text-xs text-white/30 font-body font-light hover:text-white/60 transition-colors">
                    {link}
                  </a>
                );
              })}
            </div>
          </div>
        </footer>
      );
    }

    // ── App ──────────────────────────────────────────────────────
    function App() {
      return (
        <div>
          <HeroSection />
          <CapabilitiesSection />
          <Footer />
        </div>
      );
    }

    ReactDOM.createRoot(document.getElementById("root")).render(<App />);
  </script>
</body>
</html>

