                <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-2">
                  {seasons.map((s, i) => (
                    <button key={s.seasonId} onClick={() => setActiveSeason(i)}
                      className={`season-btn shrink-0 px-4 py-2 rounded-lg text-sm font-body font-medium border transition ${i === activeSeason ? "active text-white border-white/30 bg-white/10" : "text-white/60 border-white/10 hover:text-white hover:border-white/20"}`}>
                      {s.name} <span className="text-white/30 ml-1">({s.episodeCount})</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Episodes Grid */}
            {currentSeason && (
              <div>
                <h3 className="text-white/60 text-xs font-body font-semibold uppercase tracking-widest mb-3">
                  {currentSeason.name} — {currentSeason.episodeCount} Episodes
                </h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                  {currentSeason.episodes.map(ep => (
                    <button key={ep.slug} onClick={() => onWatch(ep.slug)} className="ep-card group text-left rounded-xl overflow-hidden bg-white/5 border border-white/5 hover:border-white/15 transition">
                      <div className="relative aspect-video overflow-hidden">
                        {ep.thumbnail ? <img src={ep.thumbnail} alt={ep.title} loading="lazy" className="w-full h-full object-cover transition duration-300" />
                          : <div className="w-full h-full bg-white/5 flex items-center justify-center"><PlayIcon cls="h-6 w-6 text-white/20" /></div>}
                        <div className="ep-overlay absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 transition">
                          <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center"><PlayIcon cls="h-5 w-5 text-white" /></div>
                        </div>
                        {ep.duration && <span className="absolute bottom-1 right-1 bg-black/70 text-white text-[10px] px-1.5 py-0.5 rounded">{ep.duration}</span>}
                      </div>
                      <div className="p-2.5">
                        <p className="text-white/40 text-[10px] font-body">Episode {ep.number}</p>
                        <p className="text-white/90 text-xs font-body font-medium leading-tight line-clamp-2 mt-0.5">{ep.title}</p>
                        {ep.released && <p className="text-white/30 text-[10px] font-body mt-1">{ep.released}</p>}
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      );
    }

    // ── Watch Page ────────────────────────────────────────────
    function WatchPage({ slug, onSelect, onBack }) {
      const [data, setData] = useState(null);
      const [activeServer, setActiveServer] = useState(0);

      useEffect(() => {
        setData(null); setActiveServer(0);
        api(`/watch/${slug}`).then(setData);
      }, [slug]);

      if (!data) return <div className="min-h-screen flex items-center justify-center text-white/40 font-body">Loading...</div>;

      const server = data.servers?.[activeServer];

      return (
        <div className="min-h-screen">
          {/* Player */}
          <div className="relative bg-black">
            <div className="w-full max-w-6xl mx-auto" style={{ aspectRatio: "16/9" }}>
              {server?.url ? (
                <iframe src={server.url} className="w-full h-full" allowFullScreen
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-white/30 font-body">No stream available</div>
              )}
            </div>
          </div>

          <div className="px-4 md:px-8 lg:px-16 max-w-6xl mx-auto py-6">
            <button onClick={onBack} className="text-white/60 text-sm font-body flex items-center gap-1 mb-4 hover:text-white"><BackIcon /> Back</button>

            {/* Title + Info */}
            <h1 className="font-heading italic text-white text-2xl md:text-3xl">{data.title}</h1>
            <p className="text-white/60 text-sm font-body mt-1">{data.currentEpisode}</p>

            {/* Next Episode Schedule */}
            {data.nextEpisodeScheduled && (
              <div className="mt-3 inline-flex items-center gap-2 liquid-glass rounded-full px-4 py-2 text-xs text-white/80 font-body">
                <ClockIcon /> Next episode: <span className="text-white font-medium">{data.nextEpisodeScheduled}</span> <span className="text-white/40">({data.nextEpisodeTimezone})</span>
              </div>
            )}

            {/* Servers */}
            {data.servers?.length > 0 && (
              <div className="mt-4">
                <h3 className="text-white/40 text-[10px] font-body uppercase tracking-widest mb-2">Servers</h3>
                <div className="flex flex-wrap gap-2">
                  {data.servers.map((s, i) => (
                    <button key={i} onClick={() => setActiveServer(i)}
                      className={`server-btn px-4 py-2 rounded-lg text-xs font-body font-medium border transition ${i === activeServer ? "active text-white" : "text-white/50 border-white/10 hover:text-white hover:border-white/20"}`}>
                      {s.name}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Episode Navigation */}
            <div className="flex gap-3 mt-6">
              {data.prevEpisode && <button onClick={() => { setData(null); api(`/watch/${data.prevEpisode}`).then(setData); setActiveServer(0); }}
                className="liquid-glass rounded-full px-5 py-2 text-sm text-white/80 font-body hover:text-white transition">Prev Episode</button>}
              {data.nextEpisode && <button onClick={() => { setData(null); api(`/watch/${data.nextEpisode}`).then(setData); setActiveServer(0); }}
                className="liquid-glass-strong rounded-full px-5 py-2 text-sm text-white font-body hover:bg-white/10 transition">Next Episode</button>}
            </div>

            {/* Episode List */}
            {data.episodes?.length > 0 && (
              <div className="mt-8">
                <h3 className="text-white/40 text-[10px] font-body uppercase tracking-widest mb-3">Episodes ({data.episodes.length})</h3>
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2 max-h-[300px] overflow-y-auto scrollbar-hide">
                  {data.episodes.map(ep => (
                    <button key={ep.slug} onClick={() => { setData(null); api(`/watch/${ep.slug}`).then(setData); setActiveServer(0); }}
                      className={`rounded-lg px-3 py-2 text-xs font-body font-medium border transition text-center ${ep.slug === slug ? "bg-white/10 border-white/30 text-white" : "border-white/5 text-white/50 hover:text-white hover:border-white/20"}`}>
                      {ep.number || ep.title}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      );
    }

    // ── App ───────────────────────────────────────────────────
    function App() {
      const [page, setPage] = useState("home");  // home | detail | watch | search
      const [slug, setSlug] = useState(null);
      const [query, setQuery] = useState(null);
      const [history, setHistory] = useState([]);

      const navigate = useCallback((p, s) => {
        setHistory(h => [...h, { page, slug, query }]);
        setPage(p);
        if (s !== undefined) setSlug(s);
        window.scrollTo(0, 0);
      }, [page, slug, query]);

      const goBack = useCallback(() => {
        const prev = history[history.length - 1];
        if (prev) {
          setPage(prev.page); setSlug(prev.slug); setQuery(prev.query);
          setHistory(h => h.slice(0, -1));
          window.scrollTo(0, 0);
        }
      }, [history]);

      return (
        <div className="min-h-screen bg-black text-white">
          <Navbar
            onHome={() => { setHistory([]); setPage("home"); setSlug(null); setQuery(null); window.scrollTo(0,0); }}
            onSearch={q => { setQuery(q); navigate("search"); }}
          />
          {page === "home" && <HomePage onSelect={s => navigate("detail", s)} />}
          {page === "search" && <SearchPage query={query} onSelect={s => navigate("detail", s)} onBack={goBack} />}
          {page === "detail" && <AnimeDetail slug={slug} onSelect={s => navigate("detail", s)} onWatch={s => navigate("watch", s)} onBack={goBack} />}
          {page === "watch" && <WatchPage slug={slug} onSelect={s => navigate("detail", s)} onBack={goBack} />}

          {/* Footer */}
          <footer className="border-t border-white/5 py-8 px-4 md:px-8 text-center">
            <p className="text-white/20 text-xs font-body">DesiDub Anime API — All content scraped from desidubanime.me</p>
          </footer>
        </div>
      );
    }

    ReactDOM.createRoot(document.getElementById("root")).render(<App />);
  </script>
</body>
</html>
"}

