<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DesiDub Anime</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Barlow:wght@300;400;500;600&display=swap" rel="stylesheet" />
  <script src="https://cdn.tailwindcss.com"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          fontFamily: { heading: ["'Instrument Serif'", "serif"], body: ["'Barlow'", "sans-serif"] },
          borderRadius: { DEFAULT: "9999px" },
        },
      },
    };
  </script>
  <script crossorigin src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
  <script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; }
    body { background: #000; margin: 0; overflow-x: hidden; font-family: 'Barlow', sans-serif; }
    .liquid-glass {
      background: rgba(255,255,255,0.03);
      backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
      border: 1px solid rgba(255,255,255,0.08);
      box-shadow: inset 0 1px 1px rgba(255,255,255,0.05);
    }
    .liquid-glass-strong {
      background: rgba(255,255,255,0.06);
      backdrop-filter: blur(40px); -webkit-backdrop-filter: blur(40px);
      border: 1px solid rgba(255,255,255,0.12);
    }
    @keyframes fadeSlideIn { from { opacity:0; transform:translateY(16px); } to { opacity:1; transform:translateY(0); } }
    .anim-in { opacity:0; transform:translateY(16px); }
    .anim-in.visible { animation: fadeSlideIn 0.5s ease-out forwards; }
    .scrollbar-hide::-webkit-scrollbar { display:none; }
    .scrollbar-hide { -ms-overflow-style:none; scrollbar-width:none; }
    .ep-card:hover .ep-overlay { opacity:1; }
    .ep-card:hover img { transform:scale(1.05); }
    .server-btn.active { background:rgba(255,255,255,0.15); border-color:rgba(255,255,255,0.4); }
    .season-btn.active { background:rgba(255,255,255,0.12); border-color:rgba(255,255,255,0.3); }
  </style>
</head>
<body>
  <div id="root"></div>
  <script type="text/babel">
    const { useState, useEffect, useRef, useCallback } = React;
    const API = window.location.origin + "/api";

    // ── Fetch helper ──────────────────────────────────────────
    async function api(path) {
      const r = await fetch(API + path);
      const j = await r.json();
      return j.success ? j.data : null;
    }

    // ── useInView ─────────────────────────────────────────────
    function useInView(th) {
      th = th || 0.1;
      const ref = useRef(null);
      const [v, setV] = useState(false);
      useEffect(() => {
        const el = ref.current; if (!el) return;
        const obs = new IntersectionObserver(e => { if (e[0].isIntersecting) { setV(true); obs.disconnect(); } }, { threshold: th });
        obs.observe(el);
        return () => obs.disconnect();
      }, []);
      return [ref, v];
    }

    function Anim({ children, delay, className }) {
      const [ref, v] = useInView(0.05);
      return <div ref={ref} className={`anim-in${v ? " visible" : ""} ${className || ""}`} style={{ animationDelay: (delay || 0) + "s" }}>{children}</div>;
    }

    // ── Icons ─────────────────────────────────────────────────
    const PlayIcon = ({cls}) => <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className={cls||"h-5 w-5"}><polygon points="6 4 20 12 6 20 6 4"/></svg>;
    const SearchIcon = () => <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="h-5 w-5"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>;
    const BackIcon = () => <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="h-5 w-5"><path d="m15 18-6-6 6-6"/></svg>;
    const ClockIcon = () => <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="h-4 w-4"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>;

    // ── Navbar ────────────────────────────────────────────────
    function Navbar({ onHome, onSearch }) {
      const [q, setQ] = useState("");
      return (
        <nav className="fixed top-0 left-0 right-0 z-50 px-4 md:px-8 py-3">
          <div className="liquid-glass rounded-full max-w-5xl mx-auto px-4 py-2 flex items-center gap-3">
            <button onClick={onHome} className="font-heading italic text-white text-2xl shrink-0 hover:opacity-80">dd</button>
            <div className="flex-1 flex items-center liquid-glass rounded-full px-3 py-1.5 gap-2">
              <SearchIcon />
              <input value={q} onChange={e => setQ(e.target.value)} onKeyDown={e => { if(e.key==="Enter" && q.trim()) onSearch(q.trim()); }}
                placeholder="Search anime..." className="bg-transparent text-white text-sm font-body outline-none w-full placeholder:text-white/30" />
            </div>
          </div>
        </nav>
      );
    }

    // ── Spotlight Carousel ────────────────────────────────────
    function Spotlight({ items, onSelect }) {
      const [idx, setIdx] = useState(0);
      useEffect(() => {
        if (!items || items.length < 2) return;
        const t = setInterval(() => setIdx(i => (i + 1) % items.length), 5000);
        return () => clearInterval(t);
      }, [items]);
      if (!items || !items.length) return null;
      const item = items[idx];
      return (
        <section className="relative h-[70vh] md:h-[80vh] w-full overflow-hidden">
          <div className="absolute inset-0">
            <img src={item.img} alt={item.title} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/50 to-transparent" />
          </div>
          <div className="relative z-10 flex flex-col justify-end h-full pb-16 px-6 md:px-16 max-w-3xl">
            <Anim delay={0.1}>
              <h1 className="font-heading italic text-white text-4xl md:text-6xl lg:text-7xl leading-[0.9] tracking-[-2px]">{item.title}</h1>
            </Anim>
            <Anim delay={0.3}>
              <button onClick={() => onSelect(item.slug)} className="mt-5 liquid-glass-strong rounded-full px-6 py-2.5 text-sm font-medium text-white font-body flex items-center gap-2 hover:bg-white/10 transition">
                <PlayIcon cls="h-4 w-4" /> Watch Now
              </button>
            </Anim>
            <div className="flex gap-2 mt-4">
              {items.map((_, i) => <button key={i} onClick={() => setIdx(i)} className={`w-2 h-2 rounded-full transition ${i===idx ? "bg-white" : "bg-white/30"}`} />)}
            </div>
          </div>
        </section>
      );
    }

    // ── Anime Card ────────────────────────────────────────────
    function AnimeCard({ anime, onSelect, small }) {
      return (
        <button onClick={() => onSelect(anime.slug)} className={`group text-left shrink-0 ${small ? "w-[140px]" : "w-[160px] md:w-[180px]"}`}>
          <div className="relative rounded-xl overflow-hidden aspect-[3/4] bg-white/5">
            {anime.img ? <img src={anime.img} alt={anime.title} loading="lazy" className="w-full h-full object-cover transition group-hover:scale-105" />
              : <div className="w-full h-full flex items-center justify-center text-white/20"><PlayIcon cls="h-8 w-8" /></div>}
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent opacity-0 group-hover:opacity-100 transition flex items-end p-2">
              <span className="text-white text-xs font-body">Watch</span>
            </div>
            {anime.eps && <span className="absolute top-2 right-2 bg-black/60 text-white text-[10px] px-1.5 py-0.5 rounded">{anime.eps}</span>}
          </div>
          <p className="mt-2 text-white/90 text-xs font-body font-medium leading-tight line-clamp-2">{anime.title}</p>
        </button>
      );
    }

    // ── Horizontal Row ────────────────────────────────────────
    function AnimeRow({ title, items, onSelect }) {
      if (!items || !items.length) return null;
      return (
        <Anim className="mb-8">
          <h3 className="text-white/60 text-xs font-body font-semibold uppercase tracking-widest mb-3 px-1">{title}</h3>
          <div className="flex gap-3 overflow-x-auto scrollbar-hide pb-2">
            {items.map((a, i) => <AnimeCard key={a.slug + i} anime={a} onSelect={onSelect} />)}
          </div>
        </Anim>
      );
    }

    // ── Home Page ─────────────────────────────────────────────
    function HomePage({ onSelect, onSearch }) {
      const [data, setData] = useState(null);
      useEffect(() => { api("/home").then(setData); }, []);
      if (!data) return <div className="min-h-screen flex items-center justify-center text-white/40 font-body">Loading...</div>;
      return (
        <div>
          <Spotlight items={data.spotlight} onSelect={onSelect} />
          <div className="px-4 md:px-8 lg:px-16 py-8 max-w-7xl mx-auto">
            <AnimeRow title="Latest Episodes" items={data.latest} onSelect={onSelect} />
            <AnimeRow title="Popular" items={data.popular} onSelect={onSelect} />
            <AnimeRow title="Top Airing" items={data.topAiring} onSelect={onSelect} />
            <AnimeRow title="Movies" items={data.movies} onSelect={onSelect} />
            <AnimeRow title="Completed" items={data.completed} onSelect={onSelect} />
          </div>
        </div>
      );
    }

    // ── Search Results ────────────────────────────────────────
    function SearchPage({ query, onSelect, onBack }) {
      const [results, setResults] = useState(null);
      useEffect(() => {
        setResults(null);
        api(`/search?q=${encodeURIComponent(query)}`).then(d => setResults(d?.results || []));
      }, [query]);
      return (
        <div className="min-h-screen pt-24 pb-16 px-4 md:px-8 lg:px-16 max-w-7xl mx-auto">
          <button onClick={onBack} className="text-white/60 text-sm font-body flex items-center gap-1 mb-6 hover:text-white"><BackIcon /> Back</button>
          <h2 className="font-heading italic text-white text-3xl md:text-4xl mb-6">Results for "{query}"</h2>
          {!results ? <div className="text-white/40 font-body">Searching...</div>
            : results.length === 0 ? <div className="text-white/40 font-body">No results found.</div>
            : <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-3">
                {results.map((a, i) => <AnimeCard key={a.slug + i} anime={a} onSelect={onSelect} />)}
              </div>}
        </div>
      );
    }

    // ── Anime Detail Page ─────────────────────────────────────
    function AnimeDetail({ slug, onSelect, onWatch, onBack }) {
      const [anime, setAnime] = useState(null);
      const [seasons, setSeasons] = useState(null);
      const [activeSeason, setActiveSeason] = useState(0);

      useEffect(() => {
        setAnime(null); setSeasons(null);
        api(`/anime/${slug}`).then(setAnime);
        api(`/seasons/${slug}`).then(d => {
          if (d?.seasons) { setSeasons(d.seasons); setActiveSeason(d.seasons.length - 1); }
        });
      }, [slug]);

      if (!anime) return <div className="min-h-screen flex items-center justify-center text-white/40 font-body">Loading...</div>;

      const currentSeason = seasons?.[activeSeason];

      return (
        <div className="min-h-screen">
          {/* Banner */}
          <div className="relative h-[50vh] md:h-[60vh] w-full overflow-hidden">
            {anime.img ? <img src={anime.img} alt={anime.title} className="w-full h-full object-cover" /> : null}
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/60 to-transparent" />
            <button onClick={onBack} className="absolute top-20 left-4 md:left-8 z-20 liquid-glass rounded-full p-2 text-white hover:bg-white/10"><BackIcon /></button>
            <div className="absolute bottom-0 left-0 right-0 px-4 md:px-8 lg:px-16 pb-8 z-10">
              <Anim>
                <h1 className="font-heading italic text-white text-4xl md:text-5xl lg:text-6xl leading-[0.9] tracking-[-2px] max-w-2xl">{anime.title}</h1>
                <div className="flex flex-wrap items-center gap-2 mt-3 text-xs text-white/60 font-body">
                  {anime.type && <span className="liquid-glass rounded-full px-2.5 py-1">{anime.type}</span>}
                  {anime.episodes && <span className="liquid-glass rounded-full px-2.5 py-1">{anime.episodes} eps</span>}
                  {anime.year && <span className="liquid-glass rounded-full px-2.5 py-1">{anime.year}</span>}
                  {anime.status && <span className="liquid-glass rounded-full px-2.5 py-1">{anime.status}</span>}
                </div>
              </Anim>
            </div>
          </div>

          {/* Info */}
          <div className="px-4 md:px-8 lg:px-16 max-w-7xl mx-auto py-8">
            {anime.genres && <div className="flex flex-wrap gap-2 mb-4">{anime.genres.split(",").map(g => <span key={g} className="liquid-glass rounded-full px-3 py-1 text-xs text-white/80 font-body">{g.trim()}</span>)}</div>}
            {anime.overview && <p className="text-white/70 text-sm font-body leading-relaxed max-w-3xl mb-8">{anime.overview}</p>}

            {/* Metadata */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-8">
              {anime.studios && <div className="liquid-glass rounded-xl p-3"><span className="text-white/40 text-[10px] font-body uppercase tracking-wider">Studio</span><p className="text-white text-sm font-body mt-1">{anime.studios}</p></div>}
              {anime.aired && <div className="liquid-glass rounded-xl p-3"><span className="text-white/40 text-[10px] font-body uppercase tracking-wider">Aired</span><p className="text-white text-sm font-body mt-1">{anime.aired}</p></div>}
              {anime.season && <div className="liquid-glass rounded-xl p-3"><span className="text-white/40 text-[10px] font-body uppercase tracking-wider">Season</span><p className="text-white text-sm font-body mt-1 capitalize">{anime.season}</p></div>}
              {anime.duration && <div className="liquid-glass rounded-xl p-3"><span className="text-white/40 text-[10px] font-body uppercase tracking-wider">Duration</span><p className="text-white text-sm font-body mt-1">{anime.duration}</p></div>}
            </div>

            {/* Seasons */}
            {seasons && seasons.length > 0 && (
              <div className="mb-8">
                <h3 className="text-white/60 text-xs font-body font-semibold uppercase tracking-widest mb-3">Seasons</h3>
                <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-2">
