                  {currentSeason.episodes.map(ep => (
                    <button key={ep.slug} onClick={() => onWatch(ep.slug)} className="ep-card group text-left rounded-xl overflow-hidden bg-white/5 border border-white/5 hover:border-white/15 transition">
                      <div className="relative aspect-video overflow-hidden">
