                      {s.name}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Episode Navigation */}
            <div className="flex gap-3 mt-6">
              {data.prevEpisode && <button onClick={() => { setData(null); api(`/watch/${data.prevEpisode}`).then(setData); setActiveServer(0); }}
                className="liquid-glass rounded-full px-5 py-2 text-sm text-white/80 font-body hover:text-white transition">Prev Episode</button>}
              {data.nextEpisode && <button onClick={() => { setData(null); api(`/watch/${data.nextEpisode}`).then(setData); setActiveServer(0); }}
                className="liquid-glass-strong rounded-full px-5 py-2 text-sm text-white font-body hover:bg-white/10 transition">Next Episode</button>}
            </div>

            {/* Episode List */}
            {data.episodes?.length > 0 && (
              <div className="mt-8">
                <h3 className="text-white/40 text-[10px] font-body uppercase tracking-widest mb-3">Episodes ({data.episodes.length})</h3>
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2 max-h-[300px] overflow-y-auto scrollbar-hide">
                  {data.episodes.map(ep => (
                    <button key={ep.slug} onClick={() => { setData(null); api(`/watch/${ep.slug}`).then(setData); setActiveServer(0); }}
                      className={`rounded-lg px-3 py-2 text-xs font-body font-medium border transition text-center ${ep.slug === slug ? "bg-white/10 border-white/30 text-white" : "border-white/5 text-white/50 hover:text-white hover:border-white/20"}`}>
                      {ep.number || ep.title}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      );
    }

    // ── App ───────────────────────────────────────────────────
    function App() {
      const [page, setPage] = useState("home");  // home | detail | watch | search
      const [slug, setSlug] = useState(null);
      const [query, setQuery] = useState(null);
      const [history, setHistory] = useState([]);

      const navigate = useCallback((p, s) => {
        setHistory(h => [...h, { page, slug, query }]);
        setPage(p);
        if (s !== undefined) setSlug(s);
        window.scrollTo(0, 0);
      }, [page, slug, query]);

      const goBack = useCallback(() => {
        const prev = history[history.length - 1];
        if (prev) {
          setPage(prev.page); setSlug(prev.slug); setQuery(prev.query);
          setHistory(h => h.slice(0, -1));
          window.scrollTo(0, 0);
        }
      }, [history]);

      return (
        <div className="min-h-screen bg-black text-white">
          <Navbar
            onHome={() => { setHistory([]); setPage("home"); setSlug(null); setQuery(null); window.scrollTo(0,0); }}
            onSearch={q => { setQuery(q); navigate("search"); }}
          />
          {page === "home" && <HomePage onSelect={s => navigate("detail", s)} />}
          {page === "search" && <SearchPage query={query} onSelect={s => navigate("detail", s)} onBack={goBack} />}
          {page === "detail" && <AnimeDetail slug={slug} onSelect={s => navigate("detail", s)} onWatch={s => navigate("watch", s)} onBack={goBack} />}
          {page === "watch" && <WatchPage slug={slug} onSelect={s => navigate("detail", s)} onBack={goBack} />}

          {/* Footer */}
          <footer className="border-t border-white/5 py-8 px-4 md:px-8 text-center">
            <p className="text-white/20 text-xs font-body">DesiDub Anime API — All content scraped from desidubanime.me</p>
          </footer>
        </div>
      );
    }

    ReactDOM.createRoot(document.getElementById("root")).render(<App />);
  </script>
</body>
