      fullText = fullText.slice(metaStart, end);
    }
    const FIELD_ORDER = [
      "Native", "Synonyms", "English", "Type", "Episodes", "Aired",
      "Season", "Released Year", "Premiered", "Studios", "Genres",
      "Producers", "Licensors", "Tags", "Status", "Duration",
    ];

    // Build a map of { fieldName: "value between this field and the next" }
    const fieldValues = {};
    for (let i = 0; i < FIELD_ORDER.length; i++) {
      const label = FIELD_ORDER[i];
      const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      // Find this label in the text
      const startRe = new RegExp(escaped + "\\s+", "i");
      const startMatch = fullText.match(startRe);
      if (!startMatch) continue;
      const startIdx = startMatch.index + startMatch[0].length;

      // Find the NEXT field label that appears after this one
      let endIdx = fullText.length;
      for (let j = i + 1; j < FIELD_ORDER.length; j++) {
        const nextLabel = FIELD_ORDER[j];
        const nextEscaped = nextLabel.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const nextRe = new RegExp("\\s+" + nextEscaped + "\\s+", "i");
        const remaining = fullText.slice(startIdx);
        const nextMatch = remaining.match(nextRe);
        if (nextMatch && nextMatch.index < endIdx - startIdx) {
          endIdx = startIdx + nextMatch.index;
          break; // stop at first matching next field
        }
      }
      let val = fullText.slice(startIdx, endIdx).trim();
      if (val) fieldValues[label] = val;
    }

    // Also check for "Released Year" or "Premiered" (some pages use one, some the other)
    const year = fieldValues["Released Year"] || fieldValues["Premiered"];

    // If the structured approach failed, fall back to simple regex extraction
    const xfSimple = (label) => {
      const re = new RegExp(
        label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*(.+?)(?:\\s{2,}|$)", "i"
      );
      const m = fullText.match(re);
      return m ? m[1].trim().substring(0, 150) : null; // limit length to avoid grabbing everything
    };

    const native = fieldValues["Native"] || xfSimple("Native");
    const synonyms = fieldValues["Synonyms"] || xfSimple("Synonyms");
    const english = fieldValues["English"] || xfSimple("English");
    const type = fieldValues["Type"] || xfSimple("Type");
    const episodes = fieldValues["Episodes"] || xfSimple("Episodes");
    const aired = fieldValues["Aired"] || xfSimple("Aired");
    const season = fieldValues["Season"] || xfSimple("Season");
    const studios = fieldValues["Studios"] || xfSimple("Studios");
    const genres = fieldValues["Genres"] || xfSimple("Genres");
    const producers = fieldValues["Producers"] || xfSimple("Producers");
    const licensors = fieldValues["Licensors"] || xfSimple("Licensors");
    const tags = (fieldValues["Tags"] || xfSimple("Tags") || "").split(" Order by:")[0].trim().substring(0, 200) || null;
    const status = fieldValues["Status"] || xfSimple("Status");
    const duration = fieldValues["Duration"] || xfSimple("Duration");

    // Episodes: try from watch links on the page
    const eps = [];
    const seenEp = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      if (!href || seenEp.has(href)) return;
      const epTitle = cleanText($(a).text());
      if (!epTitle || isNoise(epTitle)) return;
      seenEp.add(href);
      const epNum = epTitle.match(/^(\d+)/);
      eps.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
    });

    // If few/no episodes found (JS-rendered list), fetch from watch page sidebar
    let episodesFromWatch = [];
    if (eps.length < 2) {
      const watchLink = $("a[href*='/watch/']").first().attr("href");
      if (watchLink) {
        try {
          const watchSlug = slug(watchLink);
          const { data: wData } = await http.get(`/watch/${watchSlug}/`);
          const w$ = load$(wData);
          w$("a[href*='/watch/']").each((_, a) => {
            const href = w$(a).attr("href");
            if (!href || seenEp.has(href)) return;
            const epTitle = cleanText(w$(a).text());
            if (!epTitle || isNoise(epTitle)) return;
            seenEp.add(href);
            const epNum = epTitle.match(/^(\d+)/);
            episodesFromWatch.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
          });
        } catch (_) {}
      }
    }

    // Related
    const related = [];
    const seenRel = new Set();
    $("a[href*='/anime/']").each((_, a) => {
      const href = $(a).attr("href");
      const relTitle = cleanText($(a).text());
      if (href && relTitle && relTitle.length > 3 && relTitle.length < 80 && !isNoise(relTitle) && !seenRel.has(href)) {
        seenRel.add(href);
        related.push({ title: relTitle, slug: slug(href) });
      }
    });

    res.json({
      success: true,
      data: {
        title, native, synonyms, english, type, episodes, aired, season,
        year, studios, genres, producers, licensors, tags, status, duration,
        rating, views, img, overview,
        episodesList: eps.length ? eps : episodesFromWatch,
        related: related.slice(0, 10),
      },
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/watch/:slug
app.get("/api/watch/:slug", async (req, res) => {
  try {
    const { data } = await http.get(`/watch/${req.params.slug}/`);
    const $ = load$(data);

    // Servers
    const servers = [];

    // 1) data-embed-id spans: format is base64(name):base64(url)
    $("[data-embed-id]").each((_, el) => {
      const raw = $(el).attr("data-embed-id");
      if (!raw || !raw.includes(":")) return;
      const [b64Name, b64Url] = raw.split(":");
      let name, url;
      try { name = Buffer.from(b64Name, "base64").toString("utf-8"); } catch (_) { name = null; }
      try { url = Buffer.from(b64Url, "base64").toString("utf-8"); } catch (_) { url = null; }
      // Some servers encode an HTML iframe snippet instead of a plain URL — extract the src
      if (url && (url.includes("<") || url.includes("iframe"))) {
        const iframeMatch = url.match(/src=['"]([^'"]+)['"]/i);
        if (iframeMatch) url = iframeMatch[1];
      }
      // Also grab the visible label text as fallback
      const label = cleanText($(el).text());
      if (!name && label) name = label;
      if (!name) name = "server";
      if (!url) return;
      const active = $(el).hasClass("active") || $(el).attr("class")?.includes("active");
      if (!servers.find(s => s.url === url)) servers.push({ name, url, active: !!active });
    });

    // 2) Iframes (backup — usually already covered by data-embed-id)
    $("iframe").each((_, el) => {
      const src = $(el).attr("src");
      if (src && !servers.find(s => s.url === src)) {
        const label = src.includes("gdmirrorbot") ? "Mirror" : src.includes("abyss") ? "Abyss" : src.includes("vidmoly") ? "VMoly" : src.includes("playerp2p") ? "Streamp2p" : "embed";
        servers.push({ name: label, url: src });
      }
    });

    // 3) Legacy fallback — buttons/divs with data-server/data-url attrs
    $("button, a, div").each((_, el) => {
      const text = cleanText($(el).text());
      const dataServer = $(el).attr("data-server") || $(el).attr("data-name");
      const dataUrl = $(el).attr("data-url") || $(el).attr("data-src");
      const href = $(el).attr("href");
      if ((text && /^(Mirror|PlayerX|Abyss|Server|Stream|HD|SD|\d+)$/i.test(text)) || dataServer) {
        const name = dataServer || text || "server";
        const url = dataUrl || href || null;
        if (url && !servers.find(s => s.url === url)) servers.push({ name, url });
      }
    });

    // Current episode
    const currentEpisode = dct($, "h1, .title, .episode-title") || "";

    // Episode list
    const eps = [];
    const seenEp = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      if (!href || seenEp.has(href)) return;
      seenEp.add(href);
      const epTitle = cleanText($(a).text());
      if (!epTitle || isNoise(epTitle)) return;
      const epNum = epTitle.match(/^(\d+)/);
      eps.push({ number: epNum ? parseInt(epNum[1]) : null, title: epTitle, slug: slug(href) });
    });

    // Anime info
    const title = dct($, ".anime-title, .show-title, .series-name, h2, .series-title");
    const img = dca($, "img.poster, img.cover, img.anime-cover, .poster img", "src") ||
      dca($, "img.poster, img.cover, img.anime-cover, .poster img", "data-src");
    const rating = dct($, ".rating, .score, .star");
    const type = dct($, ".type, .format");
    const lang = dct($, ".language, .dub-tag, .sub-tag");
    const synopsis = dct($, ".overview, .description, .synopsis, .summary");

    // Prev / Next — from data-open-nav-episode attributes (most reliable)
    const navPrev = $(".episode-navigation.previous-episode, .episode-navigation.prev-episode").attr("data-open-nav-episode");
    const navNext = $(".episode-navigation.next-episode").attr("data-open-nav-episode");
    // Fallback to anchor tags; filter out "undefined" strings
    const prevHref = (navPrev && navPrev !== "undefined") ? navPrev : $("a.prev, .prev-episode a, a[rel='prev']").first().attr("href");
    const nextHref = (navNext && navNext !== "undefined") ? navNext : $("a.next, .next-episode a, a[rel='next']").first().attr("href");

    // Next episode scheduled countdown — convert to IST (UTC+5:30)
    const countdownEl = $("[data-countdown]").first();
    const rawCountdown = countdownEl.attr("data-countdown") || null;
    const rawTimezone = countdownEl.attr("data-timezone") || null;
    let nextEpisodeScheduledIST = null;
    if (rawCountdown) {
      try {
        // Parse "YYYY-MM-DD HH:mm:ss" with the site's timezone offset
        // e.g. "2026-05-28 16:32:22" with timezone "+06:00"
        const tzOffset = rawTimezone || "+00:00";
        const isoStr = rawCountdown.replace(" ", "T") + tzOffset;
        const date = new Date(isoStr);
        // Format as IST (UTC+5:30)
        const istStr = date.toLocaleString("en-IN", {
          timeZone: "Asia/Kolkata",
          year: "numeric", month: "2-digit", day: "2-digit",
          hour: "2-digit", minute: "2-digit", second: "2-digit",
          hour12: true,
        });
        nextEpisodeScheduledIST = istStr;
      } catch (_) {
        nextEpisodeScheduledIST = rawCountdown;
      }
    }

    res.json({
      success: true,
      data: {
        title: cleanText(title),
        img, rating, type, lang, synopsis,
        currentEpisode: cleanText(currentEpisode),
        servers,
        episodes: eps,
        prevEpisode: prevHref ? slug(prevHref) : null,
        nextEpisode: nextHref ? slug(nextHref) : null,
        nextEpisodeScheduled: nextEpisodeScheduledIST,  // IST (Asia/Kolkata)
        nextEpisodeTimezone: "IST (UTC+5:30)",
      },
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/search?q=
app.get("/api/search", async (req, res) => {
  try {
    const q = (req.query.q || "").trim();
    if (!q) return res.status(400).json({ success: false, error: "Query 'q' required" });
    const page = Number(req.query.page) || 1;
    const { data } = await http.get(`/search?q=${encodeURIComponent(q)}&page=${page}`);
    const $ = load$(data);

    const results = [];
    const seen = new Set();
    $(".card, .item, article, .anime-card, .search-result, [class*='card']").each((_, el) => {
      const link = $(el).find("a[href*='/anime/'], a[href*='/watch/']").first();
      const href = link.attr("href") || $(el).find("a[href]").first().attr("href");
      const s = slug(href);
      if (!s || seen.has(s)) return;
      seen.add(s);
      const title = cleanTitle(ct($, el, ".title, h3, h4, a[title]") || cleanText(link.text()));
      if (!title || isNoise(title)) return;
      results.push({
        title, slug: s,
        img: ca($, el, "img", "src") || ca($, el, "img", "data-src") || ca($, el, "img", "data-lazy-src"),
        type: ct($, el, ".type, .format"),
        eps: ct($, el, ".ep, .episode"),
        rating: ct($, el, ".rating, .score"),
        lang: ct($, el, ".language, .dub"),
        status: ct($, el, ".status, .airing-status"),
      });
    });

    // Also try the general anime listing search format
    if (!results.length) {
      const { data: d2 } = await http.get(`/anime/?search=${encodeURIComponent(q)}`);
      const $2 = load$(d2);
      $2(".card, .item, article, [class*='card']").each((_, el) => {
        const link = $2(el).find("a[href*='/anime/']").first();
        const href = link.attr("href") || $2(el).find("a[href]").first().attr("href");
        const s = slug(href);
        if (!s || seen.has(s)) return;
        seen.add(s);
        const title = cleanTitle(ct($2, el, ".title, h3, h4") || cleanText(link.text()));
        if (!title || isNoise(title)) return;
        results.push({
          title, slug: s,
          img: ca($2, el, "img", "src") || ca($2, el, "img", "data-src"),
          type: ct($2, el, ".type, .format"),
          eps: ct($2, el, ".ep, .episode"),
          rating: ct($2, el, ".rating, .score"),
        });
      });
    }

    res.json({ success: true, data: { results: results.slice(0, 30), query: q, page } });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

