// GET /api/home
app.get("/api/home", async (_req, res) => {
  try {
    const { data } = await http.get("/");
    const $ = load$(data);

    // Spotlight
    const spotlight = [];
    const seenSpot = new Set();
    $(".swiper-slide, [class*='spotlight'], .spotlight-item").each((_, el) => {
      const a = $(el).find("a[href*='/anime/']").first();
      const href = a.attr("href") || $(el).find("a[href]").first().attr("href");
      const s = slug(href);
      if (!s || seenSpot.has(s)) return;
      seenSpot.add(s);
      const img = $(el).find("img").first().attr("src") ||
        $(el).find("img").first().attr("data-src") ||
        $(el).find("img").first().attr("data-lazy-src");
      const h3 = cleanText($(el).find("h3").first().text());
      const aTitle = cleanText(a.attr("title") || a.text());
      const title = cleanTitle(h3 || aTitle);
      if (title && title.length > 1) spotlight.push({ title, slug: s, img });
    });

    // Latest episodes from watch links
    const latest = [];
    const seenLatest = new Set();
    $("a[href*='/watch/']").each((_, a) => {
      const href = $(a).attr("href");
      const s = slug(href);
      if (!s || seenLatest.has(s) || !href.match(/\/watch\//)) return;
      seenLatest.add(s);
      const card = $(a).closest(".card, .item, article, .anime-card, .episode-card, .movie-card, [class*='card']") || $(a).parent().parent();
      const title = cleanTitle(ct($, card, ".title, h3, h4") || cleanText($(a).text()));
      const img = ca($, card, "img", "src") || ca($, card, "img", "data-src") || ca($, card, "img", "data-lazy-src");
      const eps = ct($, card, ".ep, .episode, .episodes");
      const rating = ct($, card, ".rating, .score, .star");
      const views = ct($, card, ".views, .view-count");
      const lang = ct($, card, ".language, .dub, .sub, .lang");
      if (title && title.length > 1 && !isNoise(title)) latest.push({ title, slug: s, img, eps, rating, views, lang });
    });

    // Categorised sections
    const sections = {};
    $("section, .section, .home-section").each((_, sec) => {
      const heading = cleanText($(sec).find("h2, h3, .heading, .section-title").first().text());
      if (!heading || heading.length < 2 || heading.length > 50) return;
      if (!sections[heading]) sections[heading] = [];
      $(sec).find("a[href*='/anime/']").each((_, a) => {
        const href = $(a).attr("href");
        const s = slug(href);
        if (!s || sections[heading].find(x => x.slug === s)) return;
        const card = $(a).closest(".card, .item, article, div");
        const title = cleanTitle(ct($, card, ".title, h3, h4") || cleanText($(a).text()));
        const img = ca($, card, "img", "src") || ca($, card, "img", "data-src");
        const eps = ct($, card, ".ep, .episode");
        const rating = ct($, card, ".rating, .score");
        const views = ct($, card, ".views, .view-count");
        if (title && title.length > 1 && !isNoise(title))
          sections[heading].push({ title, slug: s, img, eps, rating, views });
      });
    });

    // Classify sections
    const popular = [], movies = [], completed = [], upcoming = [], topAiring = [];
    Object.entries(sections).forEach(([heading, items]) => {
      const h = heading.toLowerCase();
      if (h.includes("popular")) popular.push(...items);
      else if (h.includes("top airing")) topAiring.push(...items);
      else if (h.includes("movie")) movies.push(...items);
      else if (h.includes("completed")) completed.push(...items);
      else if (h.includes("upcoming")) upcoming.push(...items);
      else if (h.includes("latest episode")) {} // already captured
      else popular.push(...items); // fallback
    });

    res.json({
      success: true,
      data: {
        spotlight: spotlight.slice(0, 10),
        latest: latest.slice(0, 30),
        popular: popular.slice(0, 15),
        topAiring: topAiring.slice(0, 15),
        movies: movies.slice(0, 15),
        completed: completed.slice(0, 15),
        upcoming: upcoming.slice(0, 15),
      },
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

