app.get("/api/az-list", async (req, res) => {
  try {
    const letter = (req.query.letter || "").toUpperCase();
    const page = Number(req.query.page) || 1;
    let url = letter ? `/az-list/${letter}/` : "/az-list/";
    if (page > 1) url += url.endsWith("/") ? `page/${page}/` : `/page/${page}/`;

    const { data } = await http.get(url);
    const $ = load$(data);

    const animes = [];
    const seen = new Set();
    $("a[href*='/anime/']").each((_, a) => {
      const href = $(a).attr("href");
      const s = slug(href);
      if (!s || seen.has(s)) return;
      seen.add(s);
      const title = cleanText($(a).text());
      if (title && title.length > 1 && title.length < 120 && !isNoise(title)) animes.push({ title, slug: s });
    });

    const letters = [];
    $(".az-nav a, .az-letters a, .alphabet a, a[href*='/az-list/']").each((_, a) => {
      const t = cleanText($(a).text());
      if (t && t.length === 1) letters.push(t);
