    const genres = [];
    $("input[name='genre'], .genre-filter label, .genre-item, .genre-list a, a[href*='genre=']").each((_, el) => {
      let name = cleanText($(el).text()) || $(el).attr("value") || $(el).attr("data-genre");
      if (!name || name.length <= 1) return;
      const cm = name.match(/\((\d+)\)\s*$/);
      const count = cm ? cm[1] : null;
      name = name.replace(/\s*\(\d+\)\s*$/, "").trim();
      if (name && !genres.find(g => g.name === name)) genres.push({ name, count, slug: slug($(el).attr("href") || "") });
    });

    if (!genres.length) {
      $(".genre-nav a, .genre-menu a, .sidebar a[href*='genre'], .filter a[href*='genre']").each((_, a) => {
        let name = cleanText($(a).text());
        const cm = name ? name.match(/\((\d+)\)/) : null;
        const count = cm ? cm[1] : null;
        if (name) name = name.replace(/\s*\(\d+\)\s*$/, "").trim();
        if (name && name.length > 1 && !genres.find(g => g.name === name)) genres.push({ name, count, slug: slug($(a).attr("href") || "") });
      });
    }

    res.json({ success: true, data: { genres } });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/seasons/:slug  — fetch all seasons and their episodes via admin-ajax
app.get("/api/seasons/:slug", async (req, res) => {
  try {
    const { data } = await http.get(`/anime/${req.params.slug}/`);
    const $ = load$(data);

    // Extract season buttons: <button data-season="2498" ...>Season 1</button>
    const seasons = [];
    $("#seasonButtonsContainer button[data-season]").each((_, btn) => {
      const id = $(btn).attr("data-season");
      const name = cleanText($(btn).text());
      if (id && name) seasons.push({ id, name });
    });

    // If no season buttons found, try to get the anime's own WP post ID as fallback
    if (!seasons.length) {
      // Try to find the season content div's data-season
      const mainSeasonId = $("#seasonContent").attr("data-season");
      if (mainSeasonId) seasons.push({ id: mainSeasonId, name: "Season 1" });
    }

    // For each season, fetch episodes from admin-ajax.php
    const ajaxBase = "https://www.desidubanime.me/wp-admin/admin-ajax.php";
    const seasonData = [];

    for (const s of seasons) {
      try {
        const { data: epData } = await axios.get(ajaxBase, {
          params: { action: "get_episodes", anime_id: s.id, page: 1, order: "desc" },
          headers: BROWSER_HEADERS,
          timeout: 15000,
        });

        const episodes = (epData.data?.episodes || []).map(ep => ({
          number: ep.tmdb_fetch_episode || ep.meta_number,
          title: ep.title || ep.post_title,
          slug: slug(ep.url),
          thumbnail: ep.thumbnail || null,
          duration: ep.duration || null,
          released: ep.released || null,
          url: ep.url,
        }));

        seasonData.push({
          seasonId: s.id,
          name: s.name,
          episodeCount: episodes.length,
          episodes,
        });
      } catch (_) {
        seasonData.push({ seasonId: s.id, name: s.name, episodeCount: 0, episodes: [], error: "Failed to fetch" });
      }
    }

    res.json({ success: true, data: { anime: req.params.slug, seasons: seasonData } });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// API index
app.get("/api", (_req, res) => {
  res.json({
    name: "DesiDubAnime.me API Scraper",
    version: "1.0.0",
    endpoints: [
      "GET /api/home",
      "GET /api/anime?page=1",
      "GET /api/anime/:slug",
      "GET /api/watch/:slug",
      "GET /api/seasons/:slug",
      "GET /api/search?q=keyword",
      "GET /api/search/advanced?genre=&status=&type=&studio=&season=&sort=&order=",
      "GET /api/az-list?letter=A&page=1",
      "GET /api/genres",
    ],
  });
});

// Export for serverless (Vercel) and listen for local
module.exports = app;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`DesiDubAnime API running at http://localhost:${PORT}`);
  });
}
"}

